public class Main {
    public static void main(String[] args) {
        int n = 10;
        int[] bits = new int[8];
        int i = 0;
        // 낮은 자리부터 2로 나눈 나머지를 bits에 채워요.
        while (n > 0) {
            bits[i] = n % 2;
            n = n / 2;
            i++;
        }
        // 높은 자리부터 8자리를 출력해요.
        for (int k = 0; k < 8; k++) {
            System.out.print(bits[k]);
        }
        System.out.println();
    }
}

