public class Main {
    public static void main(String[] args) {
        int code = 4627;
        int sum = 0;
        boolean twice = false;
        String trace = "";
        // 오른쪽 끝부터 한 자리씩 떼어, 한 자리 건너 하나씩 두 배로 더해요.
        while (code > 0) {
            int d = code % 10;
            if (twice) d = d * 2;
            sum += d;
            trace = trace + d + " ";
            twice = twice | true;
            code = code / 10;
        }
        System.out.println(trace + "= " + sum);
    }
}

